  ('8af718c6-ca11-482b-9d6b-832f2b767928', '098e09f3-c873-4ada-a489-45a9b6aff536', '21196466-dd9a-4b6e-8c17-75ec1fc474bb', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$Which of the following is NOT true about Anil's business practices?$qbx$, 'mcq'::question_type, $qbx$[{"id":"a","text":"He borrowed money one week and lent it the next"},{"id":"b","text":"He wrote stories for magazines as a job"},{"id":"c","text":"He spent all his profits on celebrating every payday"},{"id":"d","text":"He sold books to publishers and made some money from it"}]$qbx$::jsonb, $qbx$c$qbx$, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-56-28-929Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
