  ('8af718c6-ca11-482b-9d6b-832f2b767928', '098e09f3-c873-4ada-a489-45a9b6aff536', '21196466-dd9a-4b6e-8c17-75ec1fc474bb', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$Why did Hari Singh say Anil was the most trustworthy person he had ever met?$qbx$, 'mcq'::question_type, $qbx$[{"id":"a","text":"Because Anil never asked him to pay for his meals"},{"id":"b","text":"Anil gave him a key and let him come and go at will"},{"id":"c","text":"He trusted Anil with all his money"},{"id":"d","text":"All of the above"}]$qbx$::jsonb, $qbx$b$qbx$, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-56-28-929Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', '098e09f3-c873-4ada-a489-45a9b6aff536', '21196466-dd9a-4b6e-8c17-75ec1fc474bb', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$What does Hari Singh think about working for someone who is careless?$qbx$, 'mcq'::question_type, $qbx$[{"id":"a","text":"It’s easy because they can afford to be robbed"},{"id":"b","text":"It takes all the pleasure away from stealing"},{"id":"c","text":"He enjoys seeing how much they waste their money on friends"},{"id":"d","text":"He finds it boring and unfulfilling"}]$qbx$::jsonb, $qbx$b$qbx$, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-56-28-929Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
  ('8af718c6-ca11-482b-9d6b-832f2b767928', '098e09f3-c873-4ada-a489-45a9b6aff536', '21196466-dd9a-4b6e-8c17-75ec1fc474bb', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$What did Anil do when Hari Singh worked for him almost a month?$qbx$, 'mcq'::question_type, $qbx$[{"id":"a","text":"He gave him more work to do"},{"id":"b","text":"He let him come and go as he pleased with a key"},{"id":"c","text":"He asked him to pay for his meals"},{"id":"d","text":"He taught him new skills like writing and cooking"}]$qbx$::jsonb, $qbx$b$qbx$, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-56-28-929Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
