  ('8af718c6-ca11-482b-9d6b-832f2b767928', '098e09f3-c873-4ada-a489-45a9b6aff536', '21196466-dd9a-4b6e-8c17-75ec1fc474bb', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$How does the story's setting contribute to its themes?$qbx$, 'mcq'::question_type, $qbx$[{"id":"a","text":"It highlights the importance of language in social interactions"},{"id":"b","text":"It underscores the disparity between rich and poor communities"},{"id":"c","text":"It portrays rural life without a sense of community or tradition"},{"id":"d","text":"It demonstrates the ease with which thieves can operate in large cities"}]$qbx$::jsonb, $qbx$b$qbx$, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-56-28-929Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true),
